import React, { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { Menu, X, Code2 } from 'lucide-react';
import { NAV_LINKS } from '../constants';

const Navbar: React.FC = () => {
  const [isOpen, setIsOpen] = useState(false);
  const [scrolled, setScrolled] = useState(false);

  useEffect(() => {
    const handleScroll = () => {
      setScrolled(window.scrollY > 50);
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const scrollToSection = (href: string) => {
    setIsOpen(false);
    const element = document.querySelector(href);
    if (element) {
      element.scrollIntoView({ behavior: 'smooth' });
    }
  };

  return (
    <nav 
      className={`fixed top-0 left-0 right-0 z-50 transition-all duration-300 ${
        scrolled ? 'bg-primary/80 backdrop-blur-lg border-b border-white/10 py-4' : 'bg-transparent py-6'
      }`}
    >
      <div className="container mx-auto px-6 flex items-center justify-between">
        <div 
          className="flex items-center gap-2 cursor-pointer group"
          onClick={() => window.scrollTo({ top: 0, behavior: 'smooth' })}
        >
          <div className="p-2 bg-accent/10 rounded-lg group-hover:bg-accent/20 transition-colors">
            <Code2 className="text-accent w-6 h-6" />
          </div>
          <span className="font-heading font-bold text-xl tracking-tight text-white group-hover:text-accent transition-colors">
            Praveen<span className="text-accent">.</span>
          </span>
        </div>

        {/* Desktop Menu */}
        <div className="hidden md:flex items-center gap-8">
          {NAV_LINKS.map((link) => (
            <button
              key={link.name}
              onClick={() => scrollToSection(link.href)}
              className="text-sm font-medium text-gray-300 hover:text-accent transition-colors relative group"
            >
              {link.name}
              <span className="absolute -bottom-1 left-0 w-0 h-0.5 bg-accent transition-all duration-300 group-hover:w-full" />
            </button>
          ))}
          <button 
            onClick={() => scrollToSection('#contact')}
            className="px-5 py-2 bg-accent text-primary font-semibold rounded-full hover:bg-secondary_accent transition-all transform hover:scale-105 shadow-[0_0_20px_rgba(56,189,248,0.3)] hover:shadow-[0_0_30px_rgba(56,189,248,0.5)]"
          >
            Hire Me
          </button>
        </div>

        {/* Mobile Toggle */}
        <button 
          className="md:hidden text-gray-300 hover:text-white"
          onClick={() => setIsOpen(!isOpen)}
        >
          {isOpen ? <X size={24} /> : <Menu size={24} />}
        </button>
      </div>

      {/* Mobile Menu */}
      <AnimatePresence>
        {isOpen && (
          <motion.div
            initial={{ opacity: 0, height: 0 }}
            animate={{ opacity: 1, height: 'auto' }}
            exit={{ opacity: 0, height: 0 }}
            className="md:hidden bg-primary/95 backdrop-blur-xl border-b border-white/10 overflow-hidden"
          >
            <div className="flex flex-col items-center py-8 gap-6">
              {NAV_LINKS.map((link) => (
                <button
                  key={link.name}
                  onClick={() => scrollToSection(link.href)}
                  className="text-lg font-medium text-gray-300 hover:text-accent transition-colors"
                >
                  {link.name}
                </button>
              ))}
              <button 
                onClick={() => scrollToSection('#contact')}
                className="mt-4 px-8 py-3 bg-accent text-primary font-semibold rounded-full hover:bg-secondary_accent transition-all w-3/4 max-w-xs"
              >
                Hire Me
              </button>
            </div>
          </motion.div>
        )}
      </AnimatePresence>
    </nav>
  );
};

export default Navbar;

import React, { useRef, useLayoutEffect } from 'react';
import gsap from 'gsap';
import { ArrowDown, Github, Linkedin, Mail } from 'lucide-react';

const Hero: React.FC = () => {
  const containerRef = useRef<HTMLDivElement>(null);
  const textRef = useRef<HTMLDivElement>(null);
  const shapesRef = useRef<HTMLDivElement>(null);

  useLayoutEffect(() => {
    const ctx = gsap.context(() => {
      // Background blobs animation
      gsap.to(".blob", {
        y: "random(-50, 50)",
        x: "random(-50, 50)",
        duration: 5,
        repeat: -1,
        yoyo: true,
        ease: "sine.inOut",
        stagger: 1
      });

      // Text reveal animation
      const tl = gsap.timeline({ defaults: { ease: "power3.out" } });

      tl.from(".hero-text", {
        y: 100,
        opacity: 0,
        duration: 1,
        stagger: 0.15,
        skewY: 5
      })
      .from(".hero-btn", {
        y: 20,
        opacity: 0,
        duration: 0.8,
        stagger: 0.1
      }, "-=0.5")
      .from(".social-icon", {
        x: -20,
        opacity: 0,
        duration: 0.8,
        stagger: 0.1
      }, "-=0.5");

    }, containerRef);

    return () => ctx.revert();
  }, []);

  const scrollToProjects = () => {
    document.getElementById('projects')?.scrollIntoView({ behavior: 'smooth' });
  };

  return (
    <section 
      id="hero" 
      ref={containerRef}
      className="relative min-h-screen flex items-center justify-center pt-20 overflow-hidden"
    >
      {/* Background Gradients */}
      <div ref={shapesRef} className="absolute inset-0 z-0 overflow-hidden pointer-events-none">
        <div className="blob absolute top-0 -left-10 w-96 h-96 bg-accent/20 rounded-full mix-blend-screen filter blur-3xl opacity-30 animate-blob" />
        <div className="blob absolute top-20 right-0 w-80 h-80 bg-purple-500/20 rounded-full mix-blend-screen filter blur-3xl opacity-30 animate-blob animation-delay-2000" />
        <div className="blob absolute -bottom-20 left-20 w-80 h-80 bg-blue-500/20 rounded-full mix-blend-screen filter blur-3xl opacity-30 animate-blob animation-delay-4000" />
      </div>

      <div className="container mx-auto px-6 relative z-10">
        <div ref={textRef} className="max-w-4xl mx-auto text-center">
          <h2 className="hero-text text-accent font-medium tracking-wider uppercase mb-4">
            World-Class Web Developer
          </h2>
          <h1 className="hero-text text-5xl md:text-7xl lg:text-8xl font-heading font-bold mb-6 leading-tight text-white">
            Hi, I’m <br />
            <span className="text-gradient">Praveen Kumar</span>
          </h1>
          <p className="hero-text text-gray-400 text-lg md:text-xl max-w-2xl mx-auto mb-10 leading-relaxed">
            I craft high-performance, scalable web applications with confident designs and seamless user experiences. 
            Transforming complex problems into elegant digital solutions.
          </p>

          <div className="flex flex-col md:flex-row items-center justify-center gap-6 mb-12">
            <button 
              onClick={scrollToProjects}
              className="hero-btn group relative px-8 py-4 bg-accent text-primary font-bold rounded-full overflow-hidden transition-all hover:scale-105"
            >
              <div className="absolute inset-0 w-full h-full bg-white/20 translate-y-full group-hover:translate-y-0 transition-transform duration-300 ease-out" />
              <span className="relative z-10">View My Work</span>
            </button>
            <button 
              onClick={() => document.getElementById('contact')?.scrollIntoView({ behavior: 'smooth' })}
              className="hero-btn px-8 py-4 bg-white/5 text-white border border-white/10 font-bold rounded-full hover:bg-white/10 transition-all hover:scale-105 backdrop-blur-sm"
            >
              Hire Me
            </button>
          </div>

          <div className="flex justify-center gap-8 mb-16">
            <a href="#" className="social-icon text-gray-400 hover:text-accent transition-colors transform hover:-translate-y-1">
              <Github size={24} />
            </a>
            <a href="#" className="social-icon text-gray-400 hover:text-accent transition-colors transform hover:-translate-y-1">
              <Linkedin size={24} />
            </a>
            <a href="mailto:dummy@email.com" className="social-icon text-gray-400 hover:text-accent transition-colors transform hover:-translate-y-1">
              <Mail size={24} />
            </a>
          </div>
        </div>
      </div>

      <div className="absolute bottom-10 left-1/2 -translate-x-1/2 animate-bounce text-gray-500">
        <ArrowDown size={24} />
      </div>
    </section>
  );
};

export default Hero;

import React, { useRef, useLayoutEffect } from 'react';
import gsap from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';

gsap.registerPlugin(ScrollTrigger);

const About: React.FC = () => {
  const containerRef = useRef<HTMLDivElement>(null);

  useLayoutEffect(() => {
    const ctx = gsap.context(() => {
      gsap.from(".about-content", {
        scrollTrigger: {
          trigger: containerRef.current,
          start: "top 80%",
        },
        y: 50,
        opacity: 0,
        duration: 1,
        stagger: 0.2,
        ease: "power3.out"
      });
    }, containerRef);
    return () => ctx.revert();
  }, []);

  return (
    <section id="about" className="py-24 bg-dark relative overflow-hidden">
      <div className="container mx-auto px-6 relative z-10" ref={containerRef}>
        <div className="max-w-4xl mx-auto">
          <h2 className="about-content section-title text-3xl md:text-4xl font-heading font-bold mb-8 text-white">
            <span className="text-accent">/</span> About Me
          </h2>

          <div className="grid md:grid-cols-5 gap-12 items-start">
            <div className="md:col-span-3 space-y-6 text-gray-300 leading-relaxed text-lg about-content">
              <p>
                I am a passionate software engineer with a strong focus on building high-quality, user-centric web applications. 
                With years of experience in full-stack development, I bridge the gap between creative design and robust engineering.
              </p>
              <p>
                My approach is product-first: I don't just write code; I solve business problems. 
                Whether it's optimizing load times for an e-commerce giant or architecting a scalable MVP for a startup, 
                I bring the same level of precision and dedication to every project.
              </p>
              <p>
                When I'm not coding, I'm likely exploring the latest in tech, contributing to open source, or mentoring aspiring developers.
              </p>
            </div>

            <div className="md:col-span-2 about-content">
              <div className="p-6 bg-card rounded-2xl border border-white/5 hover:border-accent/30 transition-colors shadow-lg">
                <h3 className="text-xl font-bold text-white mb-4">Key Highlights</h3>
                <ul className="space-y-3">
                  {['Problem Solver', 'Clean Code Advocate', 'Performance Obsessed', 'Fast Learner'].map((item, i) => (
                    <li key={i} className="flex items-center text-gray-400">
                      <span className="w-2 h-2 bg-accent rounded-full mr-3" />
                      {item}
                    </li>
                  ))}
                </ul>
              </div>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
};

export default About;

