import React, { useEffect, useRef } from 'react';
import { TECH_ICONS } from '../constants';

const TechSphere: React.FC = () => {
  const containerRef = useRef<HTMLDivElement>(null);
  const requestRef = useRef<number>(0);
  const iconsRef = useRef<HTMLDivElement[]>([]);

  // Configuration
  const radius = 180; // Radius of the sphere
  const baseSpeed = 0.002; // Auto-rotation speed

  // State for rotation
  const rotation = useRef({ x: 0, y: 0 });
  const mouse = useRef({ x: 0, y: 0 });
  const scrollSpeed = useRef(0);

  useEffect(() => {
    // Distribute icons on a sphere using Fibonacci lattice
    const items = iconsRef.current;
    const count = items.length;
    const phi = Math.PI * (3 - Math.sqrt(5)); // Golden angle

    items.forEach((item, i) => {
      const y = 1 - (i / (count - 1)) * 2; // y goes from 1 to -1
      const radiusAtY = Math.sqrt(1 - y * y); // Radius at y
      const theta = phi * i; // Golden angle increment

      const x = Math.cos(theta) * radiusAtY;
      const z = Math.sin(theta) * radiusAtY;

      // Store initial position in dataset
      item.dataset.x = (x * radius).toString();
      item.dataset.y = (y * radius).toString();
      item.dataset.z = (z * radius).toString();
    });

    const handleMouseMove = (e: MouseEvent) => {
      if (!containerRef.current) return;
      const rect = containerRef.current.getBoundingClientRect();
      // Normalize mouse position (-1 to 1) relative to container center
      mouse.current.x = ((e.clientX - rect.left) / rect.width) * 2 - 1;
      mouse.current.y = ((e.clientY - rect.top) / rect.height) * 2 - 1;
    };

    const handleScroll = () => {
      // Add burst of speed on scroll
      scrollSpeed.current = 0.05;
    };

    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('scroll', handleScroll);

    const animate = () => {
      // Decay scroll speed
      scrollSpeed.current *= 0.95;

      // Calculate rotation speed (base + mouse influence + scroll influence)
      const targetSpeedX = (mouse.current.y * 0.01) + scrollSpeed.current;
      const targetSpeedY = (mouse.current.x * 0.01) + baseSpeed + scrollSpeed.current;

      rotation.current.x += targetSpeedX;
      rotation.current.y += targetSpeedY;

      // Rotate points
      const cx = Math.cos(rotation.current.x);
      const sx = Math.sin(rotation.current.x);
      const cy = Math.cos(rotation.current.y);
      const sy = Math.sin(rotation.current.y);

      items.forEach((item) => {
        const x = parseFloat(item.dataset.x || '0');
        const y = parseFloat(item.dataset.y || '0');
        const z = parseFloat(item.dataset.z || '0');

        // Rotation Matrix
        // Rotate around X
        const ry = y * cx - z * sx;
        const rz1 = y * sx + z * cx;

        // Rotate around Y
        const rx = x * cy + rz1 * sy;
        const rz = -x * sy + rz1 * cy;

        // Project to 2D
        // Perspective scaling
        const scale = 400 / (400 - rz); // simple perspective projection
        const alpha = (rz + radius) / (2 * radius); // Opacity based on Z

        item.style.transform = `translate3d(${rx}px, ${ry}px, ${rz}px) scale(${scale})`;
        item.style.opacity = Math.max(0.1, alpha + 0.2).toString();
        item.style.zIndex = Math.floor(scale * 100).toString();
      });

      requestRef.current = requestAnimationFrame(animate);
    };

    animate();

    return () => {
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('scroll', handleScroll);
      cancelAnimationFrame(requestRef.current);
    };
  }, []);

  return (
    <div 
      ref={containerRef} 
      className="relative w-[300px] h-[300px] md:w-[500px] md:h-[500px] flex items-center justify-center perspective-1000"
    >
      {TECH_ICONS.map((icon, i) => (
        <div
          key={i}
          ref={(el) => { if (el) iconsRef.current[i] = el; }}
          className="absolute flex items-center justify-center w-12 h-12 md:w-16 md:h-16 bg-white/10 backdrop-blur-md rounded-full shadow-lg border border-white/20 p-2 md:p-3 hover:bg-white/20 hover:border-accent transition-colors cursor-pointer"
          style={{ willChange: 'transform, opacity' }}
        >
          <img src={icon} alt="tech-icon" className="w-full h-full object-contain pointer-events-none" />
        </div>
      ))}
    </div>
  );
};

export default TechSphere;

