import React, { useEffect, useRef, useState } from 'react';
import { TECH_ICONS } from '../constants';

const TechSphere: React.FC = () => {
  const containerRef = useRef<HTMLDivElement>(null);
  const requestRef = useRef<number>(0);
  const iconsRef = useRef<(HTMLDivElement | null)[]>([]);
  const hoveredIndex = useRef<number | null>(null);
  const [radius, setRadius] = useState(180);
  const [tilt, setTilt] = useState({ x: 0, y: 0 });

  // State for rotation
  const rotation = useRef({ x: 0, y: 0 });
  const mouse = useRef({ x: 0, y: 0 });
  const scrollSpeed = useRef(0);

  // Base configuration
  const baseSpeed = 0.002;

  useEffect(() => {
    // Responsive radius logic
    const handleResize = () => {
      const width = window.innerWidth;
      if (width < 640) setRadius(120);
      else if (width < 1024) setRadius(160);
      else setRadius(200);
    };

    handleResize();
    window.addEventListener('resize', handleResize);

    const handleMouseMove = (e: MouseEvent) => {
      if (!containerRef.current) return;
      const rect = containerRef.current.getBoundingClientRect();
      // Normalize mouse position (-1 to 1)
      const x = ((e.clientX - rect.left) / rect.width) * 2 - 1;
      const y = ((e.clientY - rect.top) / rect.height) * 2 - 1;

      mouse.current.x = x;
      mouse.current.y = y;

      // Container tilt effect
      setTilt({ x: x * 15, y: -y * 15 });
    };

    const handleScroll = () => {
      scrollSpeed.current = 0.03;
    };

    window.addEventListener('mousemove', handleMouseMove);
    window.addEventListener('scroll', handleScroll);

    // Initialize positions (Golden Spiral / Fibonacci Sphere)
    const items = iconsRef.current;
    const count = TECH_ICONS.length; // Use data length
    const phi = Math.PI * (3 - Math.sqrt(5));

    items.forEach((item, i) => {
      if (!item) return;
      const y = 1 - (i / (count - 1)) * 2;
      const radiusAtY = Math.sqrt(1 - y * y);
      const theta = phi * i;

      const x = Math.cos(theta) * radiusAtY;
      const z = Math.sin(theta) * radiusAtY;

      // Store normalized coordinates on unit sphere
      item.dataset.nx = x.toString();
      item.dataset.ny = y.toString();
      item.dataset.nz = z.toString();
    });

    const animate = () => {
      scrollSpeed.current *= 0.95;

      // Rotate slower when hovering an item
      const isHovering = hoveredIndex.current !== null;
      const currentBaseSpeed = isHovering ? baseSpeed * 0.2 : baseSpeed;

      const targetSpeedX = (mouse.current.y * 0.005) + scrollSpeed.current;
      const targetSpeedY = (mouse.current.x * 0.005) + currentBaseSpeed + scrollSpeed.current;

      rotation.current.x += targetSpeedX;
      rotation.current.y += targetSpeedY;

      const cx = Math.cos(rotation.current.x);
      const sx = Math.sin(rotation.current.x);
      const cy = Math.cos(rotation.current.y);
      const sy = Math.sin(rotation.current.y);

      items.forEach((item, i) => {
        if (!item) return;

        const nx = parseFloat(item.dataset.nx || '0');
        const ny = parseFloat(item.dataset.ny || '0');
        const nz = parseFloat(item.dataset.nz || '0');

        // Apply rotation
        const ry = ny * cx - nz * sx;
        const rz1 = ny * sx + nz * cx;
        const rx = nx * cy + rz1 * sy;
        const rz = -nx * sy + rz1 * cy;

        // Apply radius
        const finalX = rx * radius;
        const finalY = ry * radius;
        const finalZ = rz * radius;

        // Perspective projection
        const scale = 400 / (400 - finalZ);
        const alpha = (finalZ + radius) / (2 * radius);

        // Hover scaling
        const isItemHovered = hoveredIndex.current === i;
        const scaleMultiplier = isItemHovered ? 1.5 : 1;
        const finalScale = scale * scaleMultiplier;

        item.style.transform = `translate3d(${finalX}px, ${finalY}px, ${finalZ}px) scale(${finalScale})`;
        item.style.opacity = Math.max(0.2, alpha + 0.2).toString();
        item.style.zIndex = Math.floor(scale * 100).toString();
      });

      requestRef.current = requestAnimationFrame(animate);
    };

    animate();

    return () => {
      window.removeEventListener('resize', handleResize);
      window.removeEventListener('mousemove', handleMouseMove);
      window.removeEventListener('scroll', handleScroll);
      cancelAnimationFrame(requestRef.current);
    };
  }, [radius]); // Re-initialize when radius changes

  return (
    <div 
      className="relative flex items-center justify-center perspective-1000"
      style={{ 
        width: radius * 2.5, 
        height: radius * 2.5,
      }}
    >
      <div 
        ref={containerRef}
        className="relative w-full h-full transform-style-3d transition-transform duration-100 ease-out"
        style={{
          transform: `rotateX(${tilt.y}deg) rotateY(${tilt.x}deg)`
        }}
      >
        {TECH_ICONS.map((tech, i) => (
          <div
            key={i}
            ref={(el) => { iconsRef.current[i] = el; }}
            onMouseEnter={() => { hoveredIndex.current = i; }}
            onMouseLeave={() => { hoveredIndex.current = null; }}
            className="absolute top-1/2 left-1/2 -ml-6 -mt-6 w-12 h-12 md:w-14 md:h-14 flex items-center justify-center bg-white/10 backdrop-blur-md rounded-full shadow-lg border border-white/20 p-2 md:p-3 hover:bg-white/30 hover:border-accent hover:shadow-[0_0_20px_rgba(56,189,248,0.5)] transition-colors cursor-pointer group"
            style={{ willChange: 'transform, opacity' }}
          >
            <img 
              src={tech.url} 
              alt={tech.name} 
              className="w-full h-full object-contain pointer-events-none" 
            />

            {/* Tooltip Name */}
            <div className="absolute -top-10 left-1/2 -translate-x-1/2 px-3 py-1 bg-accent/90 text-primary text-xs font-bold rounded-full opacity-0 group-hover:opacity-100 transition-opacity duration-300 pointer-events-none whitespace-nowrap shadow-lg backdrop-blur-sm transform translate-y-2 group-hover:translate-y-0">
